:root {
  color-scheme: light dark;
  --bg: #f7f6f3;
  --surface: #ffffff;
  --text: #1c1b1a;
  --muted: #62605c;
  --border: #ddd9d2;
  --accent: #0f766e;
  --accent-contrast: #ffffff;
  --radius: 10px;
  font-family:
    system-ui,
    -apple-system,
    'Segoe UI',
    Roboto,
    sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

#app {
  max-width: 720px;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

.app-header h1 {
  margin-bottom: 0.1rem;
}

.tagline {
  color: var(--muted);
  margin-top: 0;
}

section.composer,
section.board {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.25rem;
  margin-bottom: 1.5rem;
}

h2 {
  margin-top: 0;
  font-size: 1.1rem;
}

.field {
  margin-bottom: 0.9rem;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
}

input[type='text'],
input[type='search'],
textarea {
  font: inherit;
  padding: 0.5rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  color: var(--text);
}

textarea {
  resize: vertical;
  font-family: ui-monospace, monospace;
}

.hint {
  margin: 0;
  font-size: 0.8rem;
  color: var(--muted);
}

.hint code {
  background: var(--border);
  padding: 0 0.25em;
  border-radius: 3px;
}

button[type='submit'] {
  font: inherit;
  font-weight: 600;
  padding: 0.55rem 1.1rem;
  border: none;
  border-radius: 6px;
  background: var(--accent);
  color: var(--accent-contrast);
  cursor: pointer;
}

button[type='submit']:hover {
  filter: brightness(1.05);
}

.search-row {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  margin-bottom: 0.5rem;
}

.search-row label {
  white-space: nowrap;
}

.search-row input {
  flex: 1;
}

#results-line {
  color: var(--muted);
  font-size: 0.85rem;
  min-height: 1.2em;
  margin: 0 0 0.75rem;
}

#feed {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.note {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.9rem 1rem;
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-areas:
    'avatar title'
    'avatar body';
  column-gap: 0.7rem;
  row-gap: 0.25rem;
}

.note[aria-current='true'] {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent) inset;
}

.note-avatar {
  grid-area: avatar;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
}

.note:not(:has(.note-avatar)) .note-title {
  grid-column: 1 / -1;
}

.note:not(:has(.note-avatar)) .note-body {
  grid-column: 1 / -1;
}

.note-title {
  grid-area: title;
  font: inherit;
  font-weight: 700;
  font-size: 1.05rem;
  text-align: left;
  background: none;
  border: none;
  padding: 0;
  color: var(--text);
  cursor: pointer;
  width: fit-content;
}

.note-title:hover,
.note-title:focus-visible {
  color: var(--accent);
  text-decoration: underline;
}

.note-body {
  grid-area: body;
  color: var(--text);
  word-wrap: break-word;
}

.note-body a {
  color: var(--accent);
}

